@echo off
setlocal
rem Add-only oracle entry. Default invocation inspects; it does not start a game.
set "REPO_ROOT=%~dp0..\Armageddon-backup\armageddon-reimplementation"
if not exist "%REPO_ROOT%\launchers\launch_oracle.ps1" (
    echo [oracle] Tracked launcher missing. Original oracle files were not changed.
    exit /b 1
)
"%SystemRoot%\System32\WindowsPowerShell\v1.0\powershell.exe" -NoProfile -ExecutionPolicy Bypass -File "%REPO_ROOT%\launchers\launch_oracle.ps1" %*
exit /b %ERRORLEVEL%
